package challenge.leetcode.medium.usingARobotToPrintTheLexicographicallySmallestString;

import java.util.Stack;
import lombok.extern.slf4j.Slf4j;

/**
 * @author Administrator
 * @Created 06/06/2025,
 * @Project 3C: Competitive Coding Challenges
 * @Problem 2434
 * @Difficulty Medium
 * @Tags hash table,
 * string,
 * stack,
 * greedy
 * @link <a href="https://leetcode.com/problems/using-a-robot-to-print-the-lexicographically-smallest-string/">www.leetcode.com/2434</a>
 * @Description You are given a string <code>s</code> and a robot that currently holds an empty string <code>t</code>.
 * Apply one of the following operations until <code>s</code> and <code>t</code> <b>are both empty</b>:<br>
 * <ul>
 *     <li>Remove the <b>first</b> character of a string <code>s</code> and give it to the robot. The robot will append this character to the string <code>t</code>.</li>
 *     <li>Remove the <b>last</b> character of a string <code>t</code> and give it to the robot. The robot will write this character on paper.</li>
 * </ul>
 * <p>
 * Return <i>the <a href="https://en.wikipedia.org/wiki/Lexicographic_order">lexicographically</a> smallest string that can be written on the paper</i>.<br>
 *
 * <ul>
 * 		<li><b>Example 1:</b>
 * 			<br><b>Input:</b> {@code s = "zza"}
 * 			<br><b>Output:</b> {@code "azz"}
 * 			<br><b>Explanation:</b> Let <code>p</code> denote the written string.
 * 				<br>1. Initially <br>&#9;<code>p=""</code>, <code>s="zza"</code>, <code>t=""</code>
 * 				<br>2. Perform first operation three times <br>&#9;<code>p=""</code>, <code>s=""</code>, <code>t="zza"</code>
 * 				<br>3. Perform second operation three times <br>&#9;<code>p="azz"</code>, <code>s=""</code>, <code>t=""</code>
 * 		</li>
 * </ul>
 * <ul>
 * 		<li><b>Example 2:</b>
 * 			<br><b>Input:</b> {@code s = "bac"}
 * 			<br><b>Output:</b> {@code "abc"}
 * 			<br><b>Explanation:</b> Let <code>p</code> denote the written string.
 * 				<br>1. Perform first operation two times <br>&#9;<code>p=""</code>, <code>s="c"</code>, <code>t="ba"</code>
 * 				<br>2. Perform second operation two times <br>&#9;<code>p="ab"</code>, <code>s="c"</code>, <code>t=""</code>
 * 				<br>3. Perform first operation one times <br>&#9;<code>p="ab"</code>, <code>s=""</code>, <code>t="c"</code>
 * 				<br>4. Perform second operation one times <br>&#9;<code>p="abc"</code>, <code>s=""</code>, <code>t=""</code>
 * 		</li>
 * </ul>
 * <ul>
 * 		<li><b>Example 3:</b>
 * 			<br><b>Input:</b> {@code s = "bdda"}
 * 			<br><b>Output:</b> {@code "addb"}
 * 			<br><b>Explanation:</b> Let <code>p</code> denote the written string.
 * 				<br>1. Initially <br>&#9;<code>p=""</code>, <code>s="bdda"</code>, <code>t=""</code>
 * 				<br>2. Perform second operation four times <br>&#9;<code>p=""</code>, <code>s=""</code>, <code>t="addb"</code>
 * 				<br>3. Perform first operation four times <br>&#9;<code>p="addb"</code>, <code>s=""</code>, <code>t=""</code>
 * 		</li>
 * </ul>
 *
 * <p>
 * <b>Constraints:</b>
 * <ul>
 *     <li><code>1 &le; s.length &le; 10<sup>5</sup></code></li>
 *     <li><code>s</code> consists of only English lowercase letters.</li>
 * </ul>
 * <hr>
 * <br>
 * A lexicographically smallest string is the one that comes first in alphabetical order among all possible strings,
 * determined by comparing characters at each position until the first differing character,
 * with the smallest character winning the comparison.
 **/
@Slf4j
public class UsingARobotToPrintTheLexicographicallySmallestString
{
	/**
	 * <b>Solution scratchpad:</b>
	 * <br>
	 * <img src="data:image/jpeg;base64,"/>
	 *
	 * @param s the string to process
	 * @return the lexicographically smallest string (given the constraints/rules to the problem)
	 */
	public static String robotWithString(String s)
	{
		int n = s.length();
		char[] freqMap = new char[n];
		freqMap[n - 1] = s.charAt(n - 1);

		for (int i = n - 2; i >= 0; i--)
		{
			freqMap[i] = s.charAt(i) < freqMap[i + 1] ? s.charAt(i) : freqMap[i + 1];
		}

		StringBuilder out = new StringBuilder();
		Stack<Character> stack = new Stack<>();

		for (int i = 0; i < n; i++)
		{
			while (!stack.isEmpty() && stack.peek() <= freqMap[i])
			{
				out.append(stack.pop());
			}

			if (s.charAt(i) == freqMap[i])
			{
				out.append(s.charAt(i));
			}
			else
			{
				stack.push(s.charAt(i));
			}
		}

		while (!stack.isEmpty())
		{
			out.append(stack.pop());
		}
		return out.toString();
	}
}
